// 1. Obter clientes recebidos pelo Webhook
const webhookItem = $('Webhook - Clientes').first();
const rawBody = webhookItem.json.body ?? webhookItem.json;
const clientes = Array.isArray(rawBody) ? rawBody : (rawBody.clientes ?? rawBody.data?.clientes ?? []);

if (!Array.isArray(clientes) || clientes.length === 0) {
  throw new Error('Nenhum cliente válido recebido. Esperado: { "clientes": [...] }');
}

// 2. Obter base de investimentos
let csvText = '';
try {
  const httpItem = $('Carregar data.csv').first();
  if (typeof httpItem.json.data === 'string') csvText = httpItem.json.data;
  else if (typeof httpItem.json === 'string') csvText = httpItem.json;
} catch (e) {}

if (!csvText || !csvText.includes('perfil')) {
  csvText = `perfil,produto,minimo,rentabilidade
Conservador,Poupança,100,6.2%
Conservador,CDB Liquidez Diária,1000,12.5%
Conservador,Tesouro Selic,500,13.0%
Moderado,CDB Prefixado,1000,14.0%
Moderado,Fundo Multimercado,5000,16.0%
Moderado,Tesouro IPCA+,1000,IPCA+6.0%
Arrojado,Ações ETF,500,Variável
Arrojado,Fundo de Ações,10000,Variável
Arrojado,Criptomoedas,100,Variável`;
}

// 3. Parser do CSV
const linhasCsv = csvText.trim().split(/\r?\n/);
const catalogo = [];
for (let i = 1; i < linhasCsv.length; i++) {
  const c = linhasCsv[i].split(',').map(s => s.trim());
  if (c.length >= 4) {
    catalogo.push({
      perfil: c[0],
      produto: c[1],
      minimo: parseFloat(c[2]) || 0,
      rentabilidade: c[3]
    });
  }
}

function parseSaldo(v) {
  if (typeof v === 'number') return v;
  if (!v) return 0;
  const num = parseFloat(String(v).replace(/[^\d,.-]/g, '').replace(/\./g, '').replace(',', '.'));
  return isNaN(num) ? 0 : num;
}

function fmtBRL(num) {
  return num.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' });
}

// 4. Retornar um item por cliente para processamento individual pela IA
return clientes.map(cliente => {
  const saldoNum = parseSaldo(cliente.saldo);
  const perfil = String(cliente.perfil || '').trim();
  const produtosDoPerfil = catalogo.filter(p => p.perfil.toLowerCase() === perfil.toLowerCase());
  const produtosElegiveis = produtosDoPerfil.filter(p => saldoNum >= p.minimo);

  const produtosFormatados = (produtosElegiveis.length > 0 ? produtosElegiveis : produtosDoPerfil)
    .map(p => `- ${p.produto} (Aporte mínimo: ${fmtBRL(p.minimo)}, Rentabilidade esperada: ${p.rentabilidade})`)
    .join('\n');

  const prompt = `Você é um assessor financeiro de investimentos especializado.
Escreva uma recomendação de investimentos personalizada, amigável e profissional para o cliente abaixo:

- Nome: ${cliente.nome}
- Perfil de Investidor: ${perfil}
- Saldo Disponível para Aporte: ${cliente.saldo}
- Produtos Disponíveis e Elegíveis:
${produtosFormatados}

Instruções para o texto:
1. Cumprimente o investidor pelo primeiro nome com simpatia.
2. Reconheça o perfil de risco dele e justifique a estratégia recomendada.
3. Sugira as opções mais vantajosas da lista acima, comentando a rentabilidade e o aporte mínimo.
4. Finalize com um conselho inteligente para potencializar o patrimônio e inclua um breve aviso legal sobre riscos de mercado.`;

  return {
    json: {
      nome: cliente.nome,
      email: cliente.email,
      saldo: cliente.saldo,
      saldo_numerico: saldoNum,
      perfil: perfil,
      produtos_elegiveis: produtosElegiveis,
      prompt_ia: prompt
    }
  };
});

const items = $input.all().map(i => i.json);

const formatados = items.map(c => ({
  nome: c.nome,
  email: c.email,
  perfil: c.perfil,
  saldo_original: c.saldo,
  saldo_numerico: c.saldo_numerico,
  total_produtos_elegiveis: (c.produtos_elegiveis || []).length,
  mensagem_ia: c.response?.text || c.text || c.output || c.mensagem || "Mensagem gerada com sucesso pela IA."
}));

return [{
  json: {
    status: 'sucesso',
    tipo_execucao: 'Desafio Completo - IA Generativa (LLM)',
    timestamp: new Date().toISOString(),
    total_processado: formatados.length,
    resultados: formatados
  }
}];
